// =============================================================================
// Cosmos DB EF Core 9 Breaking Change Fixes
// Apply these to your Cosmos DB DbContext / project.
// =============================================================================

using Microsoft.EntityFrameworkCore;

// --- FIX 1: Discriminator property renamed from "Discriminator" to "$type" ---
// Existing documents use "Discriminator". Explicitly configure the old name
// so EF Core 9 can still read them.
//
//   modelBuilder.Entity<YourEntity>().HasDiscriminator<string>("Discriminator");

// --- FIX 2: id property no longer embeds the discriminator ---
// Existing documents have id = "EntityType|KeyValue" (e.g. "Product|123").
// EF Core 9 generates id = "123". Preserve the old format:
//
//   modelBuilder.Entity<YourEntity>().HasRootDiscriminatorInJsonId(true);

// --- FIX 3: Sync I/O now throws ---
// Replace all synchronous Cosmos DB calls with async equivalents.

/// <summary>
/// Example showing sync-to-async migration for Cosmos DB queries.
/// </summary>
class CosmosQueryExamples
{
    // BEFORE (throws in EF Core 9):
    //   var items = dbContext.Products.Where(p => p.Price > 10).ToList();
    //   dbContext.SaveChanges();

    // AFTER:
    async Task FixedQueryAsync(DbContext dbContext)
    {
        var items = await dbContext.Set<object>()
            .ToListAsync();               // ToList()        → ToListAsync()

        await dbContext.SaveChangesAsync(); // SaveChanges()   → SaveChangesAsync()

        // Other common replacements:
        // .First()          → await .FirstAsync()
        // .Single()         → await .SingleAsync()
        // .Count()          → await .CountAsync()
        // .Any()            → await .AnyAsync()
        // .FirstOrDefault() → await .FirstOrDefaultAsync()
    }
}

